<script setup lang="ts">
import { useLocale } from '../../locales';
const { translate } = useLocale();
import {ref,computed} from 'vue';import {Search,Plus,ArrowRight} from 'lucide-vue-next';import WorkshopHeader from '../../components/WorkshopHeader.vue';import StatusBadge from '../../components/StatusBadge.vue';import {useWorkshop} from '../../composables/useWorkshop';const {state}=useWorkshop();const search=ref('');const status=ref('All');const shown=computed(()=>state.workOrders.filter(w=>(status.value==='All'||w.status===status.value)&&`${w.id} ${w.customer} ${w.vehicle} ${w.registration}`.toLowerCase().includes(search.value.toLowerCase())))
</script>
<template><WorkshopHeader :title="translate('Work orders')" :subtitle="translate('Workshop operations')"><button class="btn-primary !min-h-10"><Plus :size="16"/>{{ translate("New order") }}</button></WorkshopHeader><div class="mx-auto max-w-[1400px] p-5 md:p-8"><div class="grid gap-3 md:grid-cols-[1fr_220px]"><label class="relative"><Search :size="18" class="absolute left-4 top-3.5 text-muted"/><input v-model="search" class="field pl-11" :placeholder="translate('Order, customer, vehicle or registration')"/></label><select v-model="status" class="field"><option :value="'All'">{{ translate("All") }}</option><option :value="(s)" v-for="s in ['Booked','Checked-in','Inspection','Waiting approval','Repair','Ready','Completed']">{{ translate((s)) }}</option></select></div><div class="mt-6 space-y-3"><RouterLink v-for="w in shown" :to="`/workshop/orders/${w.id}`" class="grid gap-4 rounded-2xl border bg-white p-5 hover:shadow-soft md:grid-cols-[100px_1fr_180px_150px_40px] md:items-center"><strong class="nums text-sm">{{ translate((w.id)) }}</strong><span><strong class="block">{{ translate((w.vehicle) + " · " + (w.registration)) }}</strong><small class="text-muted">{{ translate((w.customer) + " · " + (w.requested)) }}</small></span><span class="text-sm"><small class="block text-muted">{{ translate("Technician") }}</small>{{ translate((w.technician)) }}</span><StatusBadge :status="w.status"/><ArrowRight :size="17"/></RouterLink></div></div></template>
